/// <summary>
/// The <c>AVAWHSProcessGuidePromptContainerTypePageBuilder</c> builds a page for ask the container type
/// and then confirm.
/// </summary>
[
    ProcessGuidePageBuilderName(classStr(AVAWHSProcessGuidePromptContainerTypePageBuilder))
]
class AVAWHSProcessGuidePromptContainerTypePageBuilder extends ProcessGuidePageBuilder
{
}

Method.Source:
protected final void addDataControls(ProcessGuidePage _page)
{
    WhsrfPassthrough    pass;
    boolean             addEmpty;
    boolean             enabled;
    str                 defaultContainerTypeCode;

    pass                        = controller.parmSessionState().parmPass();

    addEmpty                    = true;
    enabled                     = true;

    if (pass.avaParmContainerType())
    {
        defaultContainerTypeCode = pass.avaParmContainerType();
    }
    else
    {
        defaultContainerTypeCode = WHSRFDefaultData::getDefaultValue(pass.lookupStr(ProcessGuideDataTypeNames::MenuItem),
                                                                     WHSDefaultDataField::ContainerType,
                                                                     pass.lookupStr(ProcessGuideDataTypeNames::UserId),
                                                                     pass.lookupStr(ProcessGuideDataTypeNames::InventLocationId),
                                                                     pass.lookupStr(ProcessGuideDataTypeNames::WMSLocationId));
    }

    _page.addLabel(ProcessGuideDataTypeNames::Scan,
                   "@NDX:AVASelectContainerType",
                   extendedTypeNum(WHSRFUndefinedDataType));

    _page.addComboBox(ProcessGuideDataTypeNames::AVAContainerType,
                      "@WAX1440",
                      extendedTypeNum(WHSDefaultContainerTypeCode),
                      ProcessGuideDelimiterHelper::getDelimitedList(tableNum(WHSContainerType), fieldNum(WHSContainerType, ContainerTypeCode), ProcessGuideDataTypeNames::ListSeparator, addEmpty),
                      enabled,
                      defaultContainerTypeCode);
}
